CREATE TABLE IF NOT EXISTS gis_parse_review_decisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), artifact_id uuid NOT NULL, parse_audit_id uuid NOT NULL, reviewer_id text NOT NULL, decision text NOT NULL CHECK (decision IN ('APPROVE_PARSING','REJECT_PARSING','HOLD','REQUEST_REPROCESSING')), rationale text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (parse_audit_id, reviewer_id))